import {predictScores} from './irt.js';
import {buildStudyPlan,weakestSkills} from './plan.js';
import {dateKey} from './learning.js';
import {sessionAnalytics} from './analytics.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const niceDate=d=>new Date(`${d}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
const duration=seconds=>seconds==null?'Not recorded':seconds<60?`${Math.round(seconds)}s`:`${Math.floor(seconds/60)}m ${Math.round(seconds%60)}s`;
export function equationBlock(q){return q.equations?.length?`<div class="equation-block" aria-label="Given equations">${q.equations.map(line=>`<div>${e(line)}</div>`).join('')}</div>`:'';}
export function predictionPanel(state,bank,compact=false){const p=predictScores(state.log,bank);return `<section class="panel prediction-panel ${compact?'compact':''}"><div class="section-heading"><div><span class="eyebrow">A SIGNAL, NOT A GUARANTEE</span><h2>Experimental score estimate</h2></div><span class="pill purple-pill">3PL IRT · LAST 20</span></div><div class="prediction-top"><div class="prediction-number"><strong>${p.total??'—'}</strong><span>${p.total?`Model range ${p.range[0]}–${p.range[1]}`:`${p.n} / 20 independent first responses`}</span></div><div class="prediction-sections">${Object.entries(p.sections).map(([name,s])=>`<div><span>${name}</span><strong>${s.score??'—'}<small>${s.score?' / 800':` · ${s.n}/5 responses`}</small></strong></div>`).join('')}</div></div>${!compact?`<div class="domain-estimates">${Object.entries(p.domains).map(([name,s])=>`<div><span>${name}</span><strong>${s.score??'—'}<small>${s.score?' proxy':` ${s.n}/3`}</small></strong></div>`).join('')}</div>`:''}<p class="estimate-disclaimer">${p.ready?'The model uses heuristic item parameters and an unvalidated SAT-scale mapping.':'Complete 20 independent first responses, with at least 5 per section, to see a total.'} No validated ±20-point accuracy. Domain values are practice proxies, not official SAT subscores. Model ranges omit unknown calibration error.</p><button class="text-link" data-action="export-stats">Export my stats.json ↗</button></section>`;}
export function personalizedHome(state,bank){const plan=buildStudyPlan(state,bank),weak=weakestSkills(state,bank)[0],task=plan.days[0];return `<div class="personalized-grid"><section class="panel personal-next"><span class="eyebrow">YOUR ORBIT, ${e(state.name.toUpperCase())}</span><h2>${e(state.name)}, here’s your next small win.</h2><p>${task?e(task.title):`Start with ${e(weak.skill)}. Your focus updates as you practice.`}</p><div class="personal-plan-meta"><span>◷ ${task?.minutes??15} minutes</span><span>${state.testDate?`Test date: ${niceDate(state.testDate)}`:'Set a test date for your daily plan'}</span></div><a href="/plan" class="button primary">Open my study plan →</a><a href="/guide" class="text-link">Rules, formulas & quick tips →</a></section><section class="panel share-landing"><div><span class="eyebrow">YOUR COVINGTON STUDY SPACE</span><h2>Scan. Study. Level up.</h2><p>Open Orbit on your phone. Progress stays on each device unless you export and import a profile.</p><a class="short-site-link" href="https://orbit.bronzekite16385.chatgpt.site">orbit.bronzekite16385.chatgpt.site</a><button class="text-link" data-action="copy-site-link">Copy study link ↗</button><span class="share-access-note">This site currently requires permission to visit.</span></div><img src="/qr-code.svg" alt="QR code for https://orbit.bronzekite16385.chatgpt.site" width="180" height="180"></section></div>${predictionPanel(state,bank,true)}<section class="panel home-sets"><div class="section-heading"><div><h2>Your study sets, at a glance.</h2><p>${state.sessions.length?'Your own results, including partial runs.':'Your first study set starts your story.'}</p></div><a href="#progress" class="text-link">All analytics →</a></div>${state.sessions.length?`<div class="set-cards">${state.sessions.slice(-3).reverse().map(s=>`<div><span>${e(s.label??({daily:'Daily Challenge',boss:'Boss Fight',plan:'Study plan',sprint:'Timed sprint'}[s.mode]??'Practice set'))}</span><strong>${s.firstTry}/${s.total}<small> first try</small></strong><p>+${s.xp} XP · ${s.attempted} attempted</p><button class="text-link" data-action="session-report" data-session="${s.id}">See this set’s report →</button></div>`).join('')}</div>`:'<button class="button secondary" data-action="practice">Start a personalized set →</button>'}</section>`;}
export function renderPlanPage(state,bank,offset=0){const plan=buildStudyPlan(state,bank),today=dateKey(),max=new Date();max.setDate(max.getDate()+730);return `<div class="page-intro"><div><div class="eyebrow">A PLAN THAT MOVES WITH YOU</div><h1>${e(state.name)}, one day at a time.</h1><p>Your next focus responds to your lowest ELO skills after every session.</p></div><span class="pill green-pill">PERSONALIZED · ON-DEVICE</span></div><form id="plan-form" class="panel plan-date-form"><div><h2>Where are we headed?</h2><p>Set your actual test date. Today’s plan stays short and focused.</p></div><label>Test date<input name="testDate" type="date" min="${today}" max="${dateKey(max)}" value="${e(state.testDate||'')}" required></label><button class="button primary">Update my plan →</button></form>${plan.status!=='ready'?`<section class="panel empty-state"><h2>${plan.status==='past'?'Ready for a new test date?':'Your daily plan starts here.'}</h2><p>Choose a date above. You can begin with a mixed baseline while you decide.</p><button class="button secondary" data-action="practice">Start a baseline →</button></section>`:`<div class="plan-summary"><span><b>${plan.remaining}</b> days until test day</span><span>Weakest measured focus: <b>${e(plan.weakest.find(s=>s.attempts)?.skill??'Baseline needed')}</b></span><span>Updated after <b>${state.sessions.length}</b> session${state.sessions.length===1?'':'s'}</span></div><div class="plan-grid">${plan.days.slice(offset,offset+14).map((task,i)=>`<article class="panel plan-day ${task.date===today?'today':''} ${task.completed?'completed':''}"><div class="plan-day-top"><span>${task.date===today?'TODAY':offset+i===1?'TOMORROW':niceDate(task.date)}</span><span class="pill ${task.completed?'green-pill':'purple-pill'}">${task.completed?'COMPLETE':`${task.minutes} MIN`}</span></div><h2>${e(task.title)}</h2><p>${task.type==='focus'?'A focused set chosen from this skill using your ELO ratings.':task.type==='boss'?'A rematch with five questions you have actually missed.':task.type==='testday'?'Review familiar ideas, check your supplies, and give yourself room to breathe.':'A mix of due reviews, fresh questions, and pacing practice.'}</p><span class="plan-skill">${e(task.skill)}</span>${task.type==='testday'?'<a class="text-link" href="/guide">Open quick-reference guide →</a>':`<button class="button ${task.completed?'secondary':'primary'}" data-action="plan-run" data-date="${task.date}" ${task.locked?'disabled':''}>${task.locked?'Unlocks after 5 distinct misses':task.completed?'Practice this focus again':'Start this session'} →</button>`}</article>`).join('')}</div><div class="pagination"><span>Days ${offset+1}–${Math.min(offset+14,plan.days.length)} of ${plan.days.length}</span><div><button class="button secondary" data-action="plan-page" data-offset="-14" ${offset===0?'disabled':''}>Previous</button><button class="button secondary" data-action="plan-page" data-offset="14" ${offset+14>=plan.days.length?'disabled':''}>Next</button></div></div>`}<section class="panel plan-method"><h3>Short, adaptable, and honest.</h3><p>Focus days prioritize your lowest local skill ratings. Boss Fights require five real past misses. Future days update as your work changes; completed plan sessions keep their original record. This is a practice schedule, not a promise of a particular score.</p></section>`;}
export function renderTutorPage(roster,bank,selectedId=null){const students=roster.students.filter(s=>s.role==='student'),allSeconds=students.reduce((n,s)=>n+s.data.sessions.reduce((t,x)=>t+(x.activeSeconds??0),0),0),selected=students.find(s=>s.id===selectedId);return `<div class="page-intro"><div><div class="eyebrow">COVINGTON TUTORING WORKSPACE</div><h1>Every student has a next step.</h1><p>Local profiles for your real tutoring sessions. No sample scores.</p></div><button class="button primary" data-action="add-student">+ Add student</button></div><div class="panel roster-notice"><strong>Saved only in this browser.</strong><span>A student’s phone does not sync here automatically. Import their exported Orbit profile to review their work on this device. Nicknames are enough.</span><label class="button secondary file-button">Import student results<input id="student-import" type="file" accept="application/json,.json"></label></div><div class="stats-grid tutor-stats"><div class="panel stat-card"><strong>${students.length}</strong><span>Student profiles</span></div><div class="panel stat-card"><strong>${Math.round(allSeconds/60)}</strong><span>Recorded active minutes</span></div><div class="panel stat-card"><strong>${students.reduce((n,s)=>n+s.data.sessions.length,0)}</strong><span>Study sets completed or saved</span></div><div class="panel stat-card"><strong>${students.filter(s=>predictScores(s.data.log,bank).ready).length}</strong><span>Profiles with an IRT baseline</span></div></div><section class="panel roster-panel"><div class="section-heading"><h2>Your students</h2><span class="pill purple-pill">LOCAL PROFILES</span></div>${students.length?`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Weakest measured skill</th><th>Recorded time</th><th>Experimental estimate</th><th>Actions</th></tr></thead><tbody>${students.map(s=>{const weak=weakestSkills(s.data,bank).find(w=>w.attempts),score=predictScores(s.data.log,bank),seconds=s.data.sessions.reduce((n,r)=>n+(r.activeSeconds??0),0);return `<tr><td><strong>${e(s.name)}</strong><small>${s.id===roster.activeId?'ACTIVE LEARNER':s.data.testDate?`Test: ${niceDate(s.data.testDate)}`:'No test date yet'}</small></td><td>${weak?`${e(weak.skill)}<small>ELO ${weak.rating}</small>`:'Needs baseline'}</td><td>${duration(seconds)}</td><td>${score.total??'—'}<small>${score.total?`${score.range[0]}–${score.range[1]} model range`:`${score.n}/20 responses`}</small></td><td><button class="text-link" data-action="student-report" data-id="${s.id}">View report</button><button class="text-link" data-action="switch-student" data-id="${s.id}">Study as student →</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>Your first student starts here.</h3><p>Add a nickname and optional test date, then start a baseline session in that profile.</p><button class="button primary" data-action="add-student">Add a student →</button></div>'}</section>${selected?`<section class="panel student-report-heading"><div><span class="eyebrow">STUDENT REPORT</span><h2>${e(selected.name)}</h2><p>${selected.data.log.length} recorded responses · ${selected.data.sessions.length} saved sessions</p></div><button class="button secondary" data-action="export-student" data-id="${selected.id}">Export this profile ↗</button></section>${predictionPanel(selected.data,bank)}<section class="panel student-focus"><h2>Next tutoring focus</h2>${weakestSkills(selected.data,bank).filter(s=>s.attempts).slice(0,5).map(s=>`<div><span>${e(s.skill)}</span><b>ELO ${s.rating}</b></div>`).join('')||'<p>Start a mixed baseline to establish measured skill ratings.</p>'}<div class="student-session-list">${selected.data.sessions.slice(-5).reverse().map(s=>`<button data-action="student-session-report" data-id="${selected.id}" data-session="${s.id}"><span>${new Date(s.ts).toLocaleDateString()} · ${e(s.label??s.mode)}</span><b>${s.firstTry}/${s.total} first try →</b></button>`).join('')}</div></section>`:''}`;}
export function analyticsPanel(session,bank){const a=session.analytics??sessionAnalytics(session,bank);return `<section class="session-analytics"><div class="analytics-heading"><span class="eyebrow">YOUR STUDY SET DEBRIEF</span><h2>See the pattern. Take the next step.</h2></div><div class="orbit-review"><span>✦ ORBIT REVIEW · ON-DEVICE</span><p>${e(a.review)}</p><small>Counts refer to practice items, not SAT score points.</small></div><h3>First-try results by domain</h3><div class="analytics-domains">${Object.entries(a.domains).map(([name,d])=>`<div><span>${e(name)}</span><strong>${d.correct}/${d.total}<small>${d.total?' · '+Math.round(d.correct/d.total*100)+'%':''}</small></strong><small>${d.timed?`${Math.round(d.seconds/d.timed)}s average`:'Time not recorded'}</small></div>`).join('')}</div><div class="pacing-insight"><h3>Pacing check</h3><p>${a.pacing.length?`${a.slow.length} question${a.slow.length===1?'':'s'} over 125% of the subject’s average budget. ${a.rushed.length} missed item${a.rushed.length===1?'':'s'} answered in under 15 seconds.`:'This older session did not record per-question times.'}</p><span>Reference averages: Math 95s · Reading & Writing 71s. Individual hard questions can take longer.</span></div><details class="time-details"><summary>Time on every question ↓</summary>${a.pacing.map(p=>`<div><button class="text-link" data-action="open-question" data-id="${p.id}">${p.id} · ${e(p.skill)}</button><span class="${p.slow?'slow-time':''}">${duration(p.seconds)}${p.slow?' · over budget':''}</span></div>`).join('')}</details><h3>Your error log</h3>${Object.keys(a.errors).length?Object.entries(a.errors).map(([type,items])=>`<details class="error-group"><summary><span>${e(type)}</span><b>${items.length} missed response${items.length===1?'':'s'}</b></summary>${items.map(x=>`<button class="text-link" data-action="open-question" data-id="${x.id}">${x.id} · ${e(x.skill)} →</button>`).join('')}</details>`).join(''):'<p class="muted small">No per-response error categories to show for this set.</p>'}<p class="analytics-note">${e(a.disclaimer)}</p></section>`;}
export function guidePage(tab='math'){const math=[['Circle area','A = πr²','r is the radius. Do not use the diameter as r.'],['Circumference','C = 2πr','This is a boundary length, not an area.'],['Rectangle / triangle','A = lw · A = ½bh','Use a perpendicular height for a triangle.'],['Right triangle','a² + b² = c²','c is the hypotenuse, opposite the right angle.'],['Special right triangles','45–45–90: x, x, x√2','30–60–90: x, x√3, 2x.'],['Circle in the coordinate plane','(x − h)² + (y − k)² = r²','The center is (h, k). Read the signs carefully.'],['Coordinate distance','d = √[(x₂ − x₁)² + (y₂ − y₁)²]','Complete the square first if the circle’s center is hidden.'],['Slope','m = (y₂ − y₁)/(x₂ − x₁)','Keep the order of the points consistent.'],['Quadratic formula','x = (−b ± √(b² − 4ac))/(2a)','First put the equation in ax² + bx + c = 0 form.'],['Vertex form','y = a(x − h)² + k','The vertex is (h, k); a controls direction and width.'],['Percent change','new = original × (1 ± rate)','Convert the percent to a decimal before multiplying.'],['Mean / probability','mean = sum/count · P = favorable/total','Probability counts outcomes from the full sample space.'],['Solid volumes','box: lwh · cylinder: πr²h','sphere: ⁴⁄₃πr³ · cone: ⅓πr²h · pyramid: ⅓lwh.'],['Angles','triangle: 180° · circle: 360° = 2π radians','Match angle units before using trigonometry.']];const reading=[['Read for evidence','Use only what the text supports.','An inference can be reasonable in real life and still lack support in this passage.'],['Words in context','Try the meaning inside the sentence.','Use nearby examples, contrasts, and explanations instead of a memorized definition alone.'],['Transitions','Name the relationship before choosing a word.','Contrast: however. Result: therefore. Example: for example. Addition: moreover.'],['Sentence boundaries','Check whether both sides can stand alone.','Two independent clauses need a period, a semicolon, or a comma plus a coordinating conjunction.'],['Agreement','Find the true subject.','Ignore interrupting phrases; “each” takes a singular verb.'],['Nonessential clauses','Pair the punctuation around an interruption.','Remove the clause briefly and check that the main sentence still works.'],['Parallel structure','Make list items match.','Compare verbs or phrases on both sides of the blank.'],['Main idea','Cover the whole passage.','Reject a choice that is too narrow, too broad, or introduces an unsupported claim.']];const tips=[['Pace with flexibility','About 95 seconds per Math question; 71 per R&W question.','These are section averages. Mark an item and return when a fresh look is more useful.'],['Use Desmos deliberately','Graph the relationship, then read the requested quantity.','An x-coordinate is not a y-coordinate. This calculator does not graph three variables; reduce a system first.'],['Eliminate with a reason','Cross out a choice you can actually disprove.','Cross-outs are reversible. They do not change the answer key or count as an attempt.'],['Check signs and units','Match what the question asks.','Radius vs radius squared, discount vs final price, and sum vs individual value are common traps.'],['Use your tutor wisely','Concept → mistake check → first step.','Teach Mode explains the same concept in simple language. Full worked review opens after two failed attempts.'],['Return, don’t just reread','Recall before flipping a flashcard.','Review due cards on later days. A short spaced return often beats one long cram session.']];const cards=tab==='math'?math:tab==='reading'?reading:tips;return `<div class="page-intro"><div><div class="eyebrow">YOUR POCKET STUDY GUIDE</div><h1>Rules. Formulas. Better moves.</h1><p>A clear reference you can use online or offline. Original summaries for independent practice.</p></div><button class="button secondary" data-action="calculator">Open Desmos ↗</button></div><div class="guide-tabs segmented">${[['math','Math formulas'],['reading','Reading & writing rules'],['tips','Pacing & test tips']].map(([key,label])=>`<button data-action="guide-tab" data-tab="${key}" class="${key===tab?'active':''}">${label}</button>`).join('')}</div><div class="guide-grid">${cards.map(([title,formula,note])=>`<article class="panel guide-card"><h2>${e(title)}</h2><strong class="${tab==='math'?'formula-text':''}">${e(formula)}</strong><p>${e(note)}</p></article>`).join('')}</div><section class="panel guide-footer-note"><p>Orbit is not affiliated with College Board, Bluebook, or Desmos. The linked calculator is operated by Desmos and requires internet. These tools reproduce common practice functions; this is not the official SAT testing application.</p></section>`;}
